function Assert-ComputeSnapshot($snapshot, [string[]]$off = @(), [bool]$clusterHealthy = $true, [bool]$expanded = $false) {
    Assert-ComputeEqual $snapshot.hostStatic $plan.baseline.hostStatic 'Outer storage/switch/NAT drift'
    Assert-ComputeEqual $snapshot.volumesStatic $plan.baseline.volumesStatic 'Volume identities drift'
    foreach ($guest in $snapshot.guestsStatic) {
        $old = @($plan.baseline.guestsStatic | Where-Object name -CEQ $guest.name)
        Assert-Compute ($old.Count -eq 1) 'Guest identity absent'
        # Before each serial node, earlier nodes are enlarged. Current node stays original until resize.
        $expectedCpu = $old[0].cpu; $expectedMemory = $old[0].memory
        if ($guest.name -cne 'LB-DC01' -and $stage -match '^(stop|resize|resume)-LB-NODE0([123])$') {
            $current = [int]$Matches[2]; $number = [int]$guest.name.Substring($guest.name.Length - 1)
            if ($number -lt $current -or ($stage.StartsWith('resume-') -and $number -eq $current)) { $expectedCpu = 16; $expectedMemory = 128GB }
        }
        Assert-Compute ($guest.cpu -eq $expectedCpu -and $guest.memory -eq $expectedMemory) 'Guest profile/order differs'
        $copy = @{}; foreach ($key in $guest.Keys) { $copy[$key] = $guest[$key] }
        $copy.cpu = $old[0].cpu; $copy.memory = $old[0].memory
        Assert-ComputeEqual $copy $old[0] 'Guest non-profile configuration drift'
        $expectedState = if ($guest.name -cin $off) { 'Off' } else { 'Running' }
        Assert-Compute ($snapshot.states[$guest.name] -ceq $expectedState) 'Required guest state differs'
    }
    foreach ($volume in $snapshot.volumes) {
        $budget = $plan.admission.volumeBudgets.PSObject.Properties[$volume.letter].Value
        Assert-Compute ($null -ne $budget -and $volume.health -ceq 'Healthy' -and $volume.free -ge $budget.freeFloorBytes) 'Volume free floor failed'
        Assert-Compute (($budget.maximumVhdBytes + $budget.runtimeBytes + $budget.metadataBytes + $budget.freeFloorBytes) -le $volume.size) 'Runtime-state reserve does not fit'
    }
    if ($expanded) {
        $capacity = $snapshot.hostCapacity
        Assert-Compute ($capacity.logicalProcessors -eq 64 -and $capacity.physicalCores -eq 32 -and $capacity.memoryBytes -ge 500GB -and $capacity.freeMemoryBytes -ge $plan.minimumOuterFreeMemoryBytes) 'Actual enlarged host capacity differs'
        Assert-Compute ($capacity.numa.Count -gt 0 -and ($capacity.numa | Measure-Object logicalProcessors -Sum).Sum -eq 64) 'NUMA topology unproved'
    }
    if ($clusterHealthy) {
        Assert-ComputeEqual $snapshot.clusterStatic $plan.baseline.clusterStatic 'Pool/CSV/member/VD identity drift'
        $h = $snapshot.clusterHealth
        Assert-Compute ($h.allNodesUp -and $h.allCsvOnline -and $h.allMirrorsHealthy -and $h.poolHealthy -and $h.quorumType -ceq 'Majority' -and $null -eq $h.witness -and $h.activeStorageJobs.Count -eq 0) 'Cluster health/quorum/storage job gate failed'
        Assert-Compute ($h.physicalFreeBytes -ge ($plan.admission.requiredPhysicalFreeBytes + $plan.admission.repairReserveBytes)) 'Physical S2D headroom insufficient'
    }
}
function Assert-QualifiedMirrorJobs($h, [bool]$compensating = $false) {
    # Exact whole-mirror association. Null device IDs are not physical attribution.
    $known = @{
        'D82EEC019A25474789543A1796B552BB' = 'UserStorage_1-Repair'
        '97F0D5071BB7314E9F51102237F77085' = 'ClusterPerformanceHistory-Repair'
        '4C06845FA8C574499A937BD3EB57736A' = 'UserStorage_2-Repair'
        '7C7DA96B2870124CADF176559F3F64F7' = 'UserStorage_3-Repair'
        '9E5467C0BAC8834987723430C063E2C3' = 'Infrastructure_1-Repair'
    }
    Assert-Compute ($plan.operationId -ceq 'smal-foundation-profile-20261110-03' -and $plan.maximumExecutionDeadline -ceq '2026-11-10T23:30:00+02:00' -and $plan.baseline.clusterStatic.poolId -ceq '{923c0194-3ed4-449a-ae14-0f62861e0ec8}') 'Different maintenance qualification operation/pool/bound'
    $seen = @{}
    foreach ($job in @($h.activeStorageJobs)) {
        $ids = @($job.affectedVirtualDiskIds)
        Assert-Compute ($ids.Count -eq 1 -and $ids[0] -is [string] -and $known.ContainsKey($ids[0]) -and $job.name -ceq $known[$ids[0]] -and $job.poolId -ceq $plan.baseline.clusterStatic.poolId) 'Repair is not an exact known same-pool whole mirror/name'
        Assert-Compute (-not $seen.ContainsKey($ids[0])) 'Duplicate whole-mirror repair association'
        $seen[$ids[0]] = $true
        if ($compensating) {
            Assert-Compute ($job.state -cin @('Suspended', 'Running')) 'Unknown compensating whole-mirror repair state'
        } else {
            Assert-Compute ($job.state -ceq 'Suspended') 'Further offline/resize allows only suspended exact mirror repairs'
        }
        foreach ($id in @($job.affectedDeviceIds)) {
            if ($null -eq $id) { continue }
            Assert-Compute ($id -is [string] -and $id -cin @($plan.transitionContract.deviceOwners.PSObject.Properties.Name)) 'Reported repair device is outside exact existing 24'
        }
    }
    Assert-Compute ($h.physicalFreeBytes -ge ($plan.admission.requiredPhysicalFreeBytes + $plan.admission.repairReserveBytes)) 'Maintenance physical headroom insufficient'
}

function Assert-ComputeMaintenanceHealth($snapshot, [string]$node, $drainProof, [bool]$compensating = $false) {
    Assert-ComputeEqual $snapshot.clusterStatic $plan.baseline.clusterStatic 'Maintenance pool/CSV/VD/bridge identity drift'
    $h = $snapshot.clusterHealth
    $owners = $plan.transitionContract.deviceOwners
    Assert-Compute ($null -ne $owners -and $h.devices.Count -eq 24) 'Sealed per-device ownership required'
    $expected = @($owners.PSObject.Properties | Where-Object Value -CEQ $node | ForEach-Object Name)
    Assert-Compute ($expected.Count -eq 8 -and $drainProof.selectedNode -ceq $node -and $drainProof.rpcReturned -eq $true -and $drainProof.eightDevicesMaintenanceVerified -eq $true) 'Exact original settled drain proof missing'
    Assert-ComputeEqual @($expected | Sort-Object) @($drainProof.deviceIds | Sort-Object) 'Drain proof device set differs'
    $survivors = @($h.nodeStates | Where-Object name -CNE $node)
    Assert-Compute ($survivors.Count -eq 2 -and @($survivors | Where-Object state -CNE 'Up').Count -eq 0) 'Two Up survivors required'
    $current = @($h.nodeStates | Where-Object name -CEQ $node)
    Assert-Compute ($current.Count -eq 1 -and $current[0].state -cin @('Down', 'Paused', 'Up')) 'Expected maintenance node state differs'
    if (-not $compensating -and $current[0].state -cne 'Down') {
        Assert-Compute ($current[0].state -ceq 'Paused') 'Current selected node is not paused for stop'
        $selected = @($h.devices | Where-Object owner -CEQ $node)
        Assert-Compute ($selected.Count -eq 8 -and @($selected | Where-Object maintenance -NE $true).Count -eq 0) 'Current selected eight devices are not in maintenance'
        Assert-ComputeEqual @($selected.id | Sort-Object) @($expected | Sort-Object) 'Current maintenance device set differs'
    }
    Assert-Compute ($h.allCsvOnline -and $h.quorumType -ceq 'Majority' -and $null -eq $h.witness -and $h.unrelatedFailures.Count -eq 0) 'Unrelated storage/quorum failure'
    Assert-Compute ($h.csvStates.Count -eq 4 -and @($h.csvStates | Where-Object { $_.state -cne 'Online' -or $_.accessible -ne $true }).Count -eq 0) 'CSV inaccessible during maintenance'
    Assert-Compute ($h.poolHealth -cin @('Healthy', 'Warning') -and $h.poolOperational.Count -gt 0 -and @($h.poolOperational | Where-Object { $_ -cnotin @('OK', 'Degraded', 'Incomplete', 'InService', 'In Service') }).Count -eq 0) 'Pool failure outside exact maintenance profile'
    foreach ($device in $h.devices) {
        Assert-Compute ($owners.PSObject.Properties[$device.id].Value -ceq $device.owner) 'Per-device owner drift'
        if ($device.owner -cne $node) {
            Assert-Compute ($device.health -ceq 'Healthy' -and ($device.operational -join '|') -ceq 'OK' -and -not $device.maintenance) 'Surviving-node device failure is not maintenance'
        } else {
            Assert-Compute ($device.health -cin @('Healthy', 'Warning') -and $device.operational.Count -gt 0 -and @($device.operational | Where-Object { $_ -cnotin @('OK', 'In Maintenance Mode', 'InMaintenanceMode', 'Starting Maintenance Mode', 'StartingMaintenanceMode', 'Lost Communication', 'LostCommunication') }).Count -eq 0) 'Unknown or unrelated selected-device failure'
        }
    }
    Assert-Compute ($h.virtualDiskStates.Count -eq 5 -and @($h.virtualDiskStates | Where-Object { $_.copies -ne 3 -or $_.health -cnotin @('Healthy', 'Warning') -or $_.operational.Count -eq 0 -or @($_.operational | Where-Object { $_ -cnotin @('OK', 'Degraded', 'Incomplete', 'InService', 'In Service') }).Count -gt 0 }).Count -eq 0) 'Virtual disk fault outside planned maintenance'
    Assert-QualifiedMirrorJobs $h $compensating

}

function Assert-ProfileInfrastructurePlacement($snapshot) {
    $capacities = if ($snapshot.nodeCapacity -is [Collections.IDictionary]) { @($snapshot.nodeCapacity.Values) } else { @($snapshot.nodeCapacity.PSObject.Properties | ForEach-Object Value) }
    $placements = @($capacities | ForEach-Object { $_.bridgePlacement } | Where-Object id -IEQ '4c6ca5cc-8c9a-499b-8ffe-c029bbfd3522')
    Assert-Compute ($placements.Count -eq 1 -and $placements[0].state -ceq 'Running' -and $placements[0].hciNode -cin @('LB-NODE02','LB-NODE03')) 'Infrastructure is not Running once on an expanded survivor'
    $owner = $placements[0].hciNode
    $guest = @($snapshot.guestsStatic | Where-Object name -CEQ $owner)
    Assert-Compute ($guest.Count -eq 1 -and $guest[0].cpu -eq 20 -and $guest[0].memory -eq 96GB -and $snapshot.states.$owner -ceq 'Running') 'Infrastructure survivor is not the admitted expanded Running guest'
}

# Exact GET-only installed-command/membership qualification. No command bodies exported.
$ProfileMocRead = {
    param([string]$expectedNode, [bool]$metadataOnly = $false, $identityBinding = $null, [bool]$readMembership = $true)
    $ErrorActionPreference = 'Stop'
    if ($expectedNode -cnotin @('LB-NODE01','LB-NODE02','LB-NODE03') -or $env:COMPUTERNAME -cne $expectedNode) { throw 'Exact MOC observer node differs' }
    $admin = Get-LocalUser -Name ASBuiltInAdmin
    if (-not $admin.Enabled -or -not $admin.SID.Value.EndsWith('-500') -or [Security.Principal.WindowsIdentity]::GetCurrent().User.Value -cne $admin.SID.Value) { throw 'MOC observer RID 500 differs' }
    function Hash-ProfileMoc([string]$text) {
        $hash = [Security.Cryptography.SHA256]::Create()
        try { return [BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($text))).Replace('-', '').ToLowerInvariant() } finally { $hash.Dispose() }
    }
    function Digest([byte[]]$bytes) {
        $hash=[Security.Cryptography.SHA256]::Create()
        try { [BitConverter]::ToString($hash.ComputeHash($bytes)).Replace('-','').ToLowerInvariant() } finally { $hash.Dispose() }
    }
    function SafeValue($Value) {
        if ($null -eq $Value) { return @{status='reported';value=$null;type='null'} }
        if ($Value -is [string] -or $Value -is [ValueType]) {
            $text=[string]$Value
            if ($text.Length -le 1024 -and $text -notmatch '-----BEGIN|\beyJ[A-Za-z0-9_-]{15,}\.|[\r\n]|(?i:password|access_token|refresh_token|client_secret|authorization|connectionstring)|://|\?') { return @{status='reported';value=$Value;type=$Value.GetType().FullName} }
        }
        @{status='withheld';type=$Value.GetType().FullName}
    }
    # These collection rules retain the previously qualified Foundation Items logic.
    function Member($Item,[string]$Name) {
        if ($null -eq $Item) {return @{present=$false;value=$null}}
        if ($Item -is [Collections.IDictionary]) {
            $keys=@($Item.Keys|Where-Object {$_ -is [string] -and $_ -ieq $Name})
            if ($keys.Count -gt 1) {throw 'Ambiguous vendor dictionary keys'}
            if ($keys.Count -eq 1) {return @{present=$true;value=$Item[$keys[0]]}}
        } else {
            $property=$Item.PSObject.Properties[$Name]
            if ($null -ne $property) {return @{present=$true;value=$property.Value}}
        }
        @{present=$false;value=$null}
    }
    function OuterItems($Value) {
        $flat=[Collections.Generic.List[object]]::new();$limit=@{visited=0}
        function AddOuter($Value,[int]$Depth) {
            $limit.visited++;if ($limit.visited -gt 256) {throw 'Outer collection traversal bound exceeded'}
            if ($Value -is [Collections.IList] -and $Value -isnot [Collections.IDictionary]) {
                if ($Depth -ge 4 -or $Value.Count -gt 64) {throw 'Outer collection depth/count exceeded'}
                foreach($entry in $Value) {AddOuter $entry ($Depth+1)}
            } else {
                if ($flat.Count -ge 64) {throw 'Normalised item count exceeded'}
                $flat.Add($Value)
            }
        }
        AddOuter $Value 0
        return ,$flat.ToArray()
    }
    function Items($Call,[string]$Envelope) {
        $data=OuterItems $Call.data
        for($depth=0;$depth -lt 3 -and $data.Count -eq 1;$depth++) {
            $members=@(@('value',$Envelope)|Select-Object -Unique|ForEach-Object {Member $data[0] $_}|Where-Object {$_.present})
            if ($members.Count -gt 1) {throw 'Ambiguous vendor collection envelope'}
            if ($members.Count -eq 0) {break}
            $collection=$members[0].value
            if ($null -eq $collection -or $collection -is [Collections.IDictionary] -or $collection -isnot [Collections.IList]) {throw 'Vendor envelope is not an explicit array/list'}
            $data=OuterItems $collection
        }
        if ($data.Count -gt 64 -or @($data|Where-Object {$null -eq $_ -or $_ -is [string] -or $_ -is [ValueType]}).Count) {throw 'Unsupported or oversized vendor result shape'}
        if ($data.Count -eq 1 -and ((Member $data[0] 'value').present -or (Member $data[0] $Envelope).present)) {throw 'Vendor envelope depth exceeded'}
        return ,$data
    }
    function RetainTypedJson([string]$Name,$Data) {
        $path=Join-Path $privateRoot ($Name+'-typed.json');$created=$false
        try {
            $jsonBudget=@{nodes=0}
            function TestJsonTree($Value,[int]$Depth=0) {
                $jsonBudget.nodes++;if($Depth -gt 22 -or $jsonBudget.nodes -gt 65536){return $false}
                if($null -eq $Value -or $Value -is [string] -or $Value -is [ValueType]){return $true}
                if($Value -is [Collections.IDictionary]){foreach($key in $Value.Keys){if($key -isnot [string] -or -not (TestJsonTree $Value[$key] ($Depth+1))){return $false}}}
                elseif($Value -is [Collections.IList]){foreach($item in $Value){if(-not (TestJsonTree $item ($Depth+1))){return $false}}}
                elseif($Value -is [pscustomobject]){foreach($property in $Value.PSObject.Properties){if($property.MemberType -ne 'NoteProperty' -or -not (TestJsonTree $property.Value ($Depth+1))){return $false}}}
                else{return $false}
                $true
            }
            if(-not (TestJsonTree $Data)){return @{status='capture-incomplete';reason='unsupported-or-over-bound-JSON-tree';fileCreated=$false;rawValuesExported=$false}}
            $warnings=@();$json=ConvertTo-Json -InputObject $Data -Depth 24 -Compress -WarningVariable warnings -WarningAction SilentlyContinue
            if($warnings.Count){return @{status='capture-incomplete';reason='serializer-depth-warning';fileCreated=$false;rawValuesExported=$false}}
            $bytes=[Text.Encoding]::UTF8.GetBytes($json)
            if($bytes.Length -gt 1048576){return @{status='capture-incomplete';reason='one-MiB-cap-exceeded';bytes=$bytes.Length;fileCreated=$false;rawValuesExported=$false}}
            $file=[IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);$created=$true
            try{$file.Write($bytes,0,$bytes.Length)}finally{$file.Dispose()}
            @{status='retained-private-JSON';path=$path;bytes=$bytes.Length;sha256=(Digest $bytes);complete=$true;rawValuesExported=$false}
        } catch {@{status='capture-incomplete';reason='serialization-or-create-only-write-failed';fileCreated=$created;existingFileNeverOverwritten=$true;errorType=$_.Exception.GetType().FullName;rawValuesExported=$false}}
    }
    function Project-ProfileMocRecord($record) {
        $fields=[Collections.Generic.List[object]]::new();$shape=[Collections.Generic.List[object]]::new();$budget=@{visited=0;complete=$true}
        function Walk-ProfileMoc($value,[string[]]$path,[int]$depth) {
            $budget.visited++;if($budget.visited -gt 256 -or $depth -gt 3){$budget.complete=$false;return}
            $names=if($value -is [Collections.IDictionary]){@($value.Keys)}else{@($value.PSObject.Properties.Name)}
            if($names.Count -gt 64){$budget.complete=$false;return}
            foreach($key in $names){
                if($key -isnot [string]){$budget.complete=$false;continue}
                $safeName=SafeValue $key
                if($safeName.status -cne 'reported'){$shape.Add(@{path=@($path);nameStatus='withheld'});continue}
                $child=if($value -is [Collections.IDictionary]){$value[$key]}else{$value.PSObject.Properties[$key].Value}
                $next=@($path)+$key
                $type=if($null -eq $child){'null'}else{$child.GetType().FullName};$safeType=SafeValue $type
                $shape.Add(@{path=@($next);clrType=$(if($safeType.status -ceq 'reported'){$safeType.value}else{'withheld-type'})})
                if($key -iin @('name','nodeName','computerName','hostName','id','nodeId','machineId','location','type')){$fields.Add(@{path=@($next);scalar=(SafeValue $child)})}
                if($key -iin @('properties','info','node','machine') -and $null -ne $child -and $child -isnot [string] -and $child -isnot [ValueType] -and $child -isnot [Collections.IList]){Walk-ProfileMoc $child $next ($depth+1)}
            }
        }
        Walk-ProfileMoc $record @() 0
        $type=SafeValue $record.GetType().FullName
        @{clrType=$(if($type.status -ceq 'reported'){$type.value}else{'withheld-type'});fields=@($fields.ToArray());shape=@($shape.ToArray());complete=$budget.complete}
    }
